mapper.select:
select r.id, r.registration_no as registrationNo, r.season_id as seasonId, r.member_id as memberId, r.player_id as playerId, r.platform, r.display_game_id as displayGameId, r.registration_status as registrationStatus, r.submitted_time as submittedTime, r.audit_time as auditTime, pp.game_nickname as playerNickname, s.season_name as seasonName from basket_tournament_open_registration r inner join basket_tournament_season s on s.id = r.season_id and s.is_delete = 0 left join basket_player_profile pp on pp.id = r.player_id and pp.is_delete = 0 where r.is_delete = 0 and r.registration_status != 0 and r.registration_no like concat('%', #{registrationNo}, '%') and r.season_id = #{seasonId}
and r.registration_status in (1, 2) and r.registration_status = 3 and r.registration_status = 4 and r.registration_status in (5, 6)
and r.registration_status in (1, 2) and r.registration_status in (5, 6) and r.registration_status = #{registrationStatus}
order by r.submitted_time desc, r.create_time desc
